parameters.jsCode:
return [
  {
    json: {
      url: $json.nist_url,
      type: "nist"
    }
  },
  {
    json: {
      url: $json.reg_url,
      type: "regulations"
    }
  }
];

const items = $input.all();
const results = [];

function flattenDescription(desc) {
  if (!desc || desc === "None") return "";
  if (typeof desc === "string") return desc;
  if (Array.isArray(desc)) {
    return desc
      .map(d => flattenDescription(d))
      .filter(Boolean)
      .join(". ");
  }
  return String(desc);
}

for (const item of items) {
  let parsed;

  try {
    parsed = typeof item.json.data === "string"
      ? JSON.parse(item.json.data)
      : item.json.data;
  } catch (e) {
    continue;
  }

  if (!Array.isArray(parsed)) continue;

  for (const section of parsed) {
    const sectionName = section.name || "Unknown Section";
    const subsections = section.subsection;

    if (!subsections || subsections === "None" || !Array.isArray(subsections)) {
      results.push({
        json: {
          text: `Section: ${sectionName}. No subsections defined.`,
          section: sectionName,
          source: "nist"
        }
      });
      continue;
    }

    for (const sub of subsections) {
      const controlName = sub.name || "";
      const description = flattenDescription(sub.description);
      const related = sub["related controls"] || sub["applies to"] || "";

      let text = `Section: ${sectionName} | Control: ${controlName}`;
      if (description) text += ` | Description: ${description}`;
      if (related && related !== "N/A" && related !== "") {
        text += ` | Related Controls: ${related}`;
      }

      results.push({
        json: {
          text: text.trim(),
          section: sectionName,
          control: controlName,
          source: "nist"
        }
      });
    }
  }
}

return results;

const items = $input.all();
const results = [];

function flattenDescription(desc) {
  if (!desc || desc === "None") return "";
  if (typeof desc === "string") return desc;
  if (Array.isArray(desc)) {
    return desc
      .map(d => flattenDescription(d))
      .filter(Boolean)
      .join(". ");
  }
  return String(desc);
}

for (const item of items) {
  let parsed;

  try {
    parsed = typeof item.json.data === "string"
      ? JSON.parse(item.json.data)
      : item.json.data;
  } catch (e) {
    continue;
  }

  if (!Array.isArray(parsed)) continue;

  for (const section of parsed) {
    const sectionName = section.name || "Unknown Section";
    const subsections = section.subsection;

    if (!subsections || subsections === "None" || !Array.isArray(subsections)) {
      results.push({
        json: {
          text: `Section: ${sectionName}. No subsections defined.`,
          section: sectionName,
          source: "regulations"
        }
      });
      continue;
    }

    for (const sub of subsections) {
      const controlName = sub.name || "";
      const description = flattenDescription(sub.description);
      const related = sub["related controls"] || sub["applies to"] || "";

      let text = `Section: ${sectionName} | Control: ${controlName}`;
      if (description) text += ` | Description: ${description}`;
      if (related && related !== "N/A" && related !== "") {
        text += ` | Related Controls: ${related}`;
      }

      // Handle regulation-specific fields
      const rights = sub["individual rights"];
      const fines = sub["fines"];
      const controller = sub["controller requirements"];

      if (rights && Array.isArray(rights)) {
        text += ` | Individual Rights: ${rights.join(", ")}`;
      }
      if (fines && fines !== "N/A" && fines !== "") {
        text += ` | Fines: ${fines}`;
      }
      if (controller) {
        text += ` | Controller Requirements: ${flattenDescription(controller)}`;
      }

      results.push({
        json: {
          text: text.trim(),
          section: sectionName,
          control: controlName,
          source: "regulations"
        }
      });
    }
  }
}

return results;

